// minerpg: recycling (designer, 2026-11-03). docs/superpowers/specs/2026-11-03-minerpg-recycling-design.md
//
// The Salvaging Table recipes for RPG gear, jewelry and relics are data, generated by tools/gen_salvage.py into
// kubejs/data/minerpg/recipe/salvaging/rpg/. Unique weapons get no recipe: they always have a rarity, so they
// recycle into rarity materials like any affixed item.
// They only get one for sure from chapter bosses, the Wither, the Dragon and Apotheosis' own loot; elsewhere it is a
// chance. So every second each player's inventory is checked, and a unique weapon without a rarity is given Epic or
// Mythic (weighted by the player's world tier, as Apotheosis does for a Dragon drop), with its affixes.

const $SalvageAffixHelper = Java.loadClass('dev.shadowsoffire.apotheosis.affix.AffixHelper')
const $SalvageLootController = Java.loadClass('dev.shadowsoffire.apotheosis.loot.LootController')
const $SalvageLootRarity = Java.loadClass('dev.shadowsoffire.apotheosis.loot.LootRarity')
const $SalvageRarityRegistry = Java.loadClass('dev.shadowsoffire.apotheosis.loot.RarityRegistry')
const $SalvageGenContext = Java.loadClass('dev.shadowsoffire.apotheosis.tiers.GenContext')
const $SalvageSet = Java.loadClass('java.util.Set')

const UNIQUE_WEAPON = /^(wizards|paladins|rogues|archers|archers_expansion|arsenal|bards_rpg|berserker_rpg|forcemaster_rpg|elemental_wizards_rpg):unique_/
const UNIQUE_RARITIES = ['apotheosis:epic', 'apotheosis:mythic']

function salvageGiveUniqueRarity(player) {
  const inv = player.inventory
  for (let i = 0; i < inv.getContainerSize(); i++) {
    var stack = inv.getItem(i)
    if (stack.isEmpty() || !UNIQUE_WEAPON.test(String(stack.id)) || $SalvageAffixHelper.hasAffixes(stack)) continue
    var ctx = $SalvageGenContext.forPlayer(player)
    var holders = $SalvageSet.of(UNIQUE_RARITIES.map(id => $SalvageRarityRegistry.INSTANCE.holder(id)))
    var rarity = $SalvageLootRarity.randomFromHolders(ctx, holders)
    // A world tier that weights neither (none in this pack) would give nothing: fall back to Epic.
    if (rarity == null) rarity = $SalvageRarityRegistry.INSTANCE.holder(UNIQUE_RARITIES[0]).get()
    inv.setItem(i, $SalvageLootController.createLootItem(stack.copy(), rarity, ctx))
  }
}

let salvageTicks = 0
ServerEvents.tick(event => {
  salvageTicks++
  if (salvageTicks % 20 != 0) return
  event.server.players.forEach(player => {
    try {
      salvageGiveUniqueRarity(player)
    } catch (err) {
      console.error('minerpg salvage: unique rarity failed for ' + player.username + ': ' + err)
    }
  })
})
